//! Accuracy gate: reverses a committed crop of the `context` fixture (accuracy-gate/, regenerated by
//! tools/gen_accuracy_gate.py) with a committed pack and asserts score floors. Everything runs in a scratch
//! directory, so no `work/`, Java or server is reachable.

use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};
use std::process::Command;

use flate2::read::GzDecoder;
use serde_json::Value;

const PACK: &str = "bmr-mc26.3-bluemap5.27.pack";

/// Percentages of the crop, set just below the measured values; the one place these are recorded.
/// Measured 2026-11-08: occupied 98.892, rendered 98.434, rendered_alike 99.969, exposed 98.487, solid_iou 99.969,
/// surface 97.998, biomes 100.0. Lower than the full fixture's because cells at the crop's edge lack neighbours.
const FLOORS: &[(&str, f64)] = &[
    ("occupied", 98.8),
    ("rendered", 98.3),
    ("rendered_alike", 99.9),
    ("exposed", 98.4),
    ("solid_iou", 99.9),
    ("surface", 97.9),
    ("biomes", 99.9),
];

fn gunzip_tree(from: &Path, to: &Path) {
    for entry in fs::read_dir(from).unwrap() {
        let path = entry.unwrap().path();
        let name = path.file_name().unwrap().to_str().unwrap();
        if path.is_dir() {
            gunzip_tree(&path, &to.join(name));
            continue;
        }
        let mut bytes = Vec::new();
        GzDecoder::new(fs::File::open(&path).unwrap()).read_to_end(&mut bytes).unwrap();
        fs::create_dir_all(to).unwrap();
        fs::write(to.join(name.strip_suffix(".gz").expect("gate data is gzipped")), bytes).unwrap();
    }
}

fn bmr(cwd: &Path, args: &[&str]) {
    let out = Command::new(env!("CARGO_BIN_EXE_bmr")).current_dir(cwd).args(args).output().unwrap();
    assert!(out.status.success(), "bmr {args:?}:\n{}", String::from_utf8_lossy(&out.stderr));
}

fn percent(report: &Value, metric: &str) -> f64 {
    let n =
        |path: &[&str]| path.iter().fold(report, |v, k| &v[k]).as_u64().unwrap_or_else(|| panic!("{path:?}")) as f64;
    let ratio = match metric {
        "occupied" | "rendered" | "exposed" => n(&[metric, "exact"]) / n(&[metric, "total"]),
        "rendered_alike" => n(&["rendered_alike"]) / n(&["rendered", "total"]),
        "solid_iou" => {
            n(&["solid", "both"]) / (n(&["solid", "original"]) + n(&["solid", "reconstructed"]) - n(&["solid", "both"]))
        }
        "surface" | "biomes" => n(&[metric, "hits"]) / n(&[metric, "total"]),
        _ => panic!("unknown metric {metric}"),
    };
    100.0 * ratio
}

#[test]
fn committed_crop_reverses_above_the_floors() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let pack: PathBuf = root.join("../../packs").join(PACK);
    let pack = pack.to_str().unwrap();
    let scratch = Path::new(env!("CARGO_TARGET_TMPDIR")).join("accuracy-gate");
    let _ = fs::remove_dir_all(&scratch);
    gunzip_tree(&root.join("tests/accuracy-gate"), &scratch);

    bmr(&scratch, &["reverse", "--mirror", "mirror", "-o", "reversed", "--pack", pack, "--window-jobs", "2"]);
    bmr(&scratch, &["score", "world", "reversed", "--mirror", "mirror", "--pack", pack, "--json", "report.json"]);

    let report: Value = serde_json::from_slice(&fs::read(scratch.join("report.json")).unwrap()).unwrap();
    let scores: Vec<(&str, f64, f64)> = FLOORS.iter().map(|&(m, floor)| (m, percent(&report, m), floor)).collect();
    println!("{scores:?}");
    let below: Vec<_> = scores.iter().filter(|(_, got, floor)| got < floor).collect();
    assert!(below.is_empty(), "below the floor (metric, got, floor): {below:?}");
}
